const SAMPLES = 480;

interface RoadPoint {
  x: number;
  y: number;
}

let table: RoadPoint[] | null = null;

/** Tabla de puntos a lo largo de la curva; se calcula una vez (así el viaje no consulta el DOM en cada fotograma). */
const buildTable = (): RoadPoint[] => {
  const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
  const path = document.createElementNS('http://www.w3.org/2000/svg', 'path');

  path.setAttribute('d', ROAD_D);
  svg.setAttribute('aria-hidden', 'true');
  svg.style.cssText = 'position:absolute;width:0;height:0;visibility:hidden';
  svg.appendChild(path);
  document.body.appendChild(svg);

  const length = path.getTotalLength();
  const points = Array.from({ length: SAMPLES + 1 }, (_, i) => {
    const { x, y } = path.getPointAtLength((length * i) / SAMPLES);

    return { x, y };
  });

  svg.remove();
  table = points;

  return points;
};

/**
 * Punto de la carretera en `t` (0-1) y hacia dónde mira el viajero en ese tramo (`facing`: 1 derecha, -1 izquierda,
 * según la dirección de avance de la carretera, aunque el viajero esté retrocediendo).
 */
export const roadPointAt = (t: number) => {
  const points = table ?? buildTable();
  const f = Math.min(1, Math.max(0, t)) * SAMPLES;
  const i = Math.min(SAMPLES - 1, Math.floor(f));
  const k = f - i;
  const a = points[i];
  const b = points[i + 1];

  // El rumbo se toma de un tramo algo más largo para que no parpadee en las curvas cerradas
  const ahead = points[Math.min(SAMPLES, i + 6)];
  const behind = points[Math.max(0, i - 6)];
  const dx = ahead.x - behind.x;

  return { x: a.x + (b.x - a.x) * k, y: a.y + (b.y - a.y) * k, dx };
};

/**
 * Avance (0-1) de la parada `index` (0-based) entre `count` paradas, repartidas a partes iguales entre la salida y
 * la meta. Un índice igual a `count` es la meta.
 */
export const stopT = (index: number, count: number) => (index >= count ? 1 : (index + 1) / (count + 1));
